content.es:
-- Cuenta cuántos productos hay en total.
-- El paso 2 pide algo bastante más útil.
SELECT COUNT(*) AS total FROM productos;

content.en:
-- Count how many products there are in total.
-- Step 2 asks for something rather more useful.
SELECT COUNT(*) AS total FROM productos;

solution.content:
SELECT   categoria, COUNT(*) AS cuantos
FROM     productos
GROUP BY categoria;
